function saveReport(def){const st=analyticsState(),copy=Object.assign({},def,{id:def&&def.id||'RPT-'+Date.now(),updatedAt:new Date().toISOString()});const i=st.savedReports.findIndex(x=>x.id===copy.id);if(i>=0)st.savedReports[i]=copy;else st.savedReports.unshift(copy);if(typeof global.saveAppData==='function')global.saveAppData();return copy;}
